import React, { useEffect, useState } from 'react';
import { getLocations, createLocation, updateLocation, deleteLocation } from '../api/location.api';

const parseCurrentUser = () => {
  try { return JSON.parse(localStorage.getItem('user')); }
  catch { return null; }
};

const LocationManagement = () => {
  const currentUser = parseCurrentUser();
  const isAdmin = currentUser?.role === 'admin';

  const [locations, setLocations] = useState([]);
  const [form, setForm] = useState({ name: '', latitude: '', longitude: '' });
  const [editId, setEditId] = useState(null);
  const [search, setSearch] = useState('');
  const [error, setError] = useState('');
  const [loading, setLoading] = useState(false);

  const fetchLocations = async () => {
    try {
      const res = await getLocations();
      setLocations(res.data || []);
    } catch { setError('Failed to load locations.'); }
  };

  useEffect(() => { fetchLocations(); }, []);

  const handleSubmit = async (e) => {
    e.preventDefault();
    setError('');
    setLoading(true);
    try {
      if (editId) {
        await updateLocation(editId, form);
      } else {
        await createLocation(form);
      }
      setForm({ name: '', latitude: '', longitude: '' });
      setEditId(null);
      fetchLocations();
    } catch (err) {
      setError(err.response?.data?.message || 'Operation failed.');
    } finally {
      setLoading(false);
    }
  };

  const handleEdit = (loc) => {
    setEditId(loc.id);
    setForm({ name: loc.name, latitude: loc.latitude, longitude: loc.longitude });
    setError('');
  };

  const handleDelete = async (id) => {
    if (!window.confirm('Delete this location?')) return;
    try {
      await deleteLocation(id);
      fetchLocations();
    } catch { setError('Delete failed.'); }
  };

  const filtered = locations.filter((l) => {
    const t = search.toLowerCase();
    return (
      l.name?.toLowerCase().includes(t) ||
      String(l.latitude).includes(t) ||
      String(l.longitude).includes(t) ||
      String(l.id).includes(t)
    );
  });

  return (
    <div>
      <div className="page-title">
        <div>
          <h2>Location Management</h2>
          <p>Manage pickup and drop-off points using coordinates.</p>
        </div>
      </div>

      {error && <div className="error-message" style={{ marginBottom: 16 }}>{error}</div>}

      <div className="form-card">
        <div className="card-header">
          <div>
            <h3 style={{ margin: 0, color: '#fff' }}>{editId ? 'Edit Location' : 'Add New Location'}</h3>
            <p style={{ color: 'var(--muted)', margin: 0 }}>
              {editId ? 'Update name or coordinates.' : 'Save a new fleet location by lat/lng.'}
            </p>
          </div>
          <input
            className="filter-input"
            placeholder="Search locations..."
            value={search}
            onChange={(e) => setSearch(e.target.value)}
          />
        </div>

        <form onSubmit={handleSubmit} className="form-grid">
          <div className="field-group">
            <label>Location Name</label>
            <input
              placeholder="e.g. Delhi Airport"
              value={form.name}
              onChange={(e) => setForm({ ...form, name: e.target.value })}
              required
            />
          </div>
          <div className="field-group">
            <label>Latitude</label>
            <input
              type="number"
              step="any"
              placeholder="e.g. 28.5562"
              value={form.latitude}
              onChange={(e) => setForm({ ...form, latitude: e.target.value })}
              required
            />
          </div>
          <div className="field-group">
            <label>Longitude</label>
            <input
              type="number"
              step="any"
              placeholder="e.g. 77.1000"
              value={form.longitude}
              onChange={(e) => setForm({ ...form, longitude: e.target.value })}
              required
            />
          </div>
          <div className="table-actions">
            <button type="submit" className="btn btn-primary" disabled={loading}>
              {loading ? 'Saving...' : editId ? 'Update Location' : 'Add Location'}
            </button>
            {editId && (
              <button type="button" className="btn btn-secondary" onClick={() => {
                setEditId(null);
                setForm({ name: '', latitude: '', longitude: '' });
                setError('');
              }}>
                Cancel
              </button>
            )}
          </div>
        </form>
      </div>

      <div className="table-card" style={{ marginTop: 20 }}>
        <div className="card-header">
          <div>
            <h3 style={{ margin: 0, color: '#fff' }}>Saved Locations</h3>
            <p style={{ color: 'var(--muted)', margin: 0 }}>
              Showing {filtered.length} of {locations.length} locations
            </p>
          </div>
        </div>
        <div style={{ overflowX: 'auto' }}>
          <table className="data-table">
            <thead>
              <tr>
                <th>ID</th>
                <th>Name</th>
                <th>Latitude</th>
                <th>Longitude</th>
                <th>Actions</th>
              </tr>
            </thead>
            <tbody>
              {filtered.length === 0 ? (
                <tr><td colSpan={5} style={{ textAlign: 'center', color: 'var(--muted)' }}>No locations found</td></tr>
              ) : filtered.map((l) => (
                <tr key={l.id}>
                  <td>{l.id}</td>
                  <td>{l.name}</td>
                  <td>{l.latitude}</td>
                  <td>{l.longitude}</td>
                  <td className="table-actions">
                    <button className="btn btn-secondary" onClick={() => handleEdit(l)}>Edit</button>
                    {isAdmin && (
                      <button className="btn btn-danger" onClick={() => handleDelete(l.id)}>Delete</button>
                    )}
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </div>
    </div>
  );
};

export default LocationManagement;
